<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import type {Collection,Workspace,WorkspaceRecord} from '@nextspace/contracts'
import {eventEditorChanges,eventEditorDraft,eventEditorFingerprint,eventAccessExplanation,type EventEditorChanges} from '@nextspace/core/event-editor.mjs'
import {convertCreationDateMode,type CreationDateDraft} from '@nextspace/core/creation-dates.mjs'
import SchedulingWeek from './SchedulingWeek.vue'
import EventReminders from './EventReminders.vue'
import EventAttendees from './EventAttendees.vue'
const props=defineProps<{record:WorkspaceRecord;records:WorkspaceRecord[];collections:Collection[];workspace:Workspace;busy:boolean;error?:string}>()
const emit=defineEmits<{save:[value:EventEditorChanges];cancel:[];dirty:[value:boolean]}>()
const original:WorkspaceRecord=JSON.parse(JSON.stringify(props.record)),fingerprint=eventEditorFingerprint(original),draft=ref(eventEditorDraft(original)),validation=ref('')
const attendeePending=ref(false)
const baseline=JSON.stringify(draft.value),changed=computed(()=>eventEditorFingerprint(props.record)!==fingerprint)
watch(()=>({draft:JSON.stringify(draft.value),pending:attendeePending.value}),value=>emit('dirty',value.draft!==baseline||value.pending),{immediate:true})
const detailsAllowed=computed(()=>props.record.eventAccess?.editDetails??!props.record.readonly),remindersAllowed=computed(()=>props.record.eventAccess?.editReminders??!props.record.readonly),attendeesAllowed=computed(()=>props.record.eventAccess?.editAttendees===true)
let previousTimed:CreationDateDraft|undefined
function toggleAllDay(event:Event){if(props.busy||!detailsAllowed.value||changed.value)return;const target=(event.target as HTMLInputElement).checked,current={start:draft.value.start,end:draft.value.end,allDay:draft.value.allDay};if(target&&!current.allDay)previousTimed=current;Object.assign(draft.value,convertCreationDateMode(current,target,'event',previousTimed))}
function chooseSlot(slot:CreationDateDraft){if(!props.busy&&!changed.value&&detailsAllowed.value)Object.assign(draft.value,slot)}
function submit(){if(props.busy||changed.value||attendeePending.value)return;validation.value='';try{emit('save',eventEditorChanges(original,draft.value))}catch(reason){validation.value=reason instanceof Error?reason.message:'Check the event details.'}}
</script>
<template><div class="event-details-editor"><span class="eyebrow">CALENDAR</span><h2>Edit event</h2><p v-if="record.eventAccess?.reason" class="field-hint">{{eventAccessExplanation(record.eventAccess.reason)}}</p><form @submit.prevent="submit"><fieldset :disabled="busy||changed"><fieldset :disabled="!detailsAllowed"><label>Event title<input v-model="draft.title" required maxlength="500"/></label><label>Location<input v-model="draft.location" maxlength="2000"/></label><label class="check-label"><input :checked="draft.allDay" type="checkbox" @change="toggleAllDay"/>All day</label><SchedulingWeek :context-key="record.id" :records="records.filter(item=>item.id!==record.id)" :collections="collections" :plans="workspace.plans" :calendar-colors="workspace.appearance.calendarColors" :start="draft.start" :end="draft.end" :all-day="draft.allDay" :disabled="busy||changed||!detailsAllowed" @change="chooseSlot"/><details><summary>Exact dates</summary><div class="form-two"><label>Start<input v-model="draft.start" :type="draft.allDay?'date':'datetime-local'" required/></label><label>End<input v-model="draft.end" :type="draft.allDay?'date':'datetime-local'" required/></label></div><p v-if="draft.allDay" class="field-hint">The end is the first day after the event.</p></details><label>Description<textarea v-model="draft.description" rows="4" maxlength="500000"/></label></fieldset><EventReminders v-model="draft.reminders" :disabled="busy||changed||!remindersAllowed" :unsupported-count="record.unsupportedReminderCount"/><EventAttendees v-model="draft.attendees" @pending="attendeePending=$event" :disabled="busy||changed||!attendeesAllowed" :organizer="record.eventScheduling?.organizer?.name||record.eventScheduling?.organizer?.uri" :reason="attendeesAllowed?undefined:record.eventAccess?.reason?eventAccessExplanation(record.eventAccess.reason):'Invitation sending is not verified for this calendar. Open it in Nextcloud to add attendees.'"/></fieldset><p v-if="changed" role="alert" class="inline-error">This event changed while you were editing. Your draft is kept here. Copy your changes and reopen the event to review its current version.</p><p v-if="validation||error" role="alert" class="inline-error">{{validation||error}}</p><div class="form-actions"><button type="button" class="button quiet" :disabled="busy" @click="emit('cancel')">Cancel</button><button class="button primary" :disabled="busy||changed||attendeePending||JSON.stringify(draft)===baseline">{{busy?'Saving…':'Save event'}}</button></div></form></div></template>
<style scoped>.event-details-editor h2{font-size:23px;margin:8px 0 16px}.event-details-editor fieldset{border:0;padding:0;min-width:0}.event-details-editor fieldset>label{margin-bottom:12px}.event-details-editor details{margin:14px 0}.event-details-editor summary{font-size:12px;cursor:pointer;margin-bottom:8px}.event-details-editor .form-actions{margin-top:16px}</style>
